CREATE VIEW nelson_brasileirao_db.vw_nelson_artilharia_geral AS
 SELECT j.id_jogador AS id,
    j.nome AS jogador,
    count(g.id_gol) AS gols,
    c.nome AS clube
   FROM ((nelson_brasileirao_db.clube c
     JOIN nelson_brasileirao_db.jogador j ON ((c.id_clube = j.clube_id)))
     JOIN nelson_brasileirao_db.gol g ON ((g.jogador_id = j.id_jogador)))
  GROUP BY j.id_jogador, j.nome, c.nome
  ORDER BY (count(g.id_gol)) DESC;


