    m.nome AS mandante,
    v.nome AS visitante
   FROM (((nelson_brasileirao_db.partida p
     JOIN nelson_brasileirao_db.clube m ON ((p.mandante_id = m.id_clube)))
     JOIN nelson_brasileirao_db.clube v ON ((p.visitante_id = v.id_clube)))
