CREATE VIEW nelson_brasileirao_db.vw_nelson_cartoes_jogador AS
 SELECT j.nome AS jogador,
    c.nome AS clube,
    count(
        CASE
            WHEN ((ca.tipo)::text = 'amarelo'::text) THEN 1
            ELSE NULL::integer
        END) AS amarelos,
    count(
        CASE
            WHEN ((ca.tipo)::text = 'vermelho'::text) THEN 1
            ELSE NULL::integer
        END) AS vermelhos,
    count(ca.id_cartao) AS "total cartões"
   FROM ((nelson_brasileirao_db.clube c
     RIGHT JOIN nelson_brasileirao_db.jogador j ON ((j.clube_id = c.id_clube)))
     LEFT JOIN nelson_brasileirao_db.cartao ca ON ((j.id_jogador = ca.jogador_id)))
  GROUP BY j.nome, c.nome
  ORDER BY (count(ca.id_cartao)) DESC;


