CREATE VIEW nelson_brasileirao_db.vw_nelson_jogadores_decisivos AS
 SELECT g.id_gol,
    j.nome AS jogador,
    c.nome AS clube,
    g.minuto,
    ((p_final.gols_m || ' x '::text) || p_final.gols_v) AS placar_final
   FROM (((((nelson_brasileirao_db.gol g
     JOIN nelson_brasileirao_db.jogador j ON ((g.jogador_id = j.id_jogador)))
     JOIN nelson_brasileirao_db.clube c ON ((j.clube_id = c.id_clube)))
     JOIN nelson_brasileirao_db.partida p ON ((g.partida_id = p.id_partida)))
     JOIN ( SELECT p_1.id_partida,
            count(
                CASE
                    WHEN (j_1.clube_id = p_1.mandante_id) THEN 1
                    ELSE NULL::integer
                END) AS gols_m,
            count(
                CASE
                    WHEN (j_1.clube_id = p_1.visitante_id) THEN 1
                    ELSE NULL::integer
                END) AS gols_v
           FROM ((nelson_brasileirao_db.partida p_1
             LEFT JOIN nelson_brasileirao_db.gol g_1 ON ((p_1.id_partida = g_1.partida_id)))
             LEFT JOIN nelson_brasileirao_db.jogador j_1 ON ((g_1.jogador_id = j_1.id_jogador)))
          GROUP BY p_1.id_partida) p_final ON ((p_final.id_partida = p.id_partida)))
     JOIN ( SELECT g_1.id_gol,
            count(
                CASE
                    WHEN (j_1.clube_id = p_1.mandante_id) THEN 1
                    ELSE NULL::integer
                END) AS gols_m_antes,
            count(
                CASE
                    WHEN (j_1.clube_id = p_1.visitante_id) THEN 1
                    ELSE NULL::integer
                END) AS gols_v_antes
           FROM (((nelson_brasileirao_db.gol g_1
             JOIN nelson_brasileirao_db.partida p_1 ON ((g_1.partida_id = p_1.id_partida)))
             LEFT JOIN nelson_brasileirao_db.gol gp ON (((gp.partida_id = p_1.id_partida) AND ((gp.minuto < g_1.minuto) OR ((gp.minuto = g_1.minuto) AND (gp.id_gol < g_1.id_gol))))))
             LEFT JOIN nelson_brasileirao_db.jogador j_1 ON ((gp.jogador_id = j_1.id_jogador)))
          GROUP BY g_1.id_gol) p_antes ON ((p_antes.id_gol = g.id_gol)))
  WHERE ((g.minuto >= 85) AND (p_antes.gols_m_antes = p_antes.gols_v_antes) AND (((j.clube_id = p.mandante_id) AND (p_final.gols_m > p_final.gols_v)) OR ((j.clube_id = p.visitante_id) AND (p_final.gols_v > p_final.gols_m))))
  ORDER BY g.minuto DESC;


